def render_source_catalog():
    import streamlit as st
    with st.expander(f"Supported sites ({len(SUPPORTED_SITES)})"):
        st.caption("Supported by the installed downloader. Search integration is available for a smaller verified set. Site changes, login requirements or paid chapters may limit downloads.")
        query = st.text_input("Find a source", key="manga_catalog_filter", placeholder="Asura, manga, scans…").casefold().strip()
        for site in SUPPORTED_SITES:
            if query and query not in site["name"].casefold():
                continue
            st.markdown("- [" + site["name"] + "](" + site["url"] + ")" + (" · browser needed" if site["browser"] else ""))
